"""QQ attachment response compatibility; generated bytes only, no network."""
import base64
import hashlib
import json
import os
import sys
import tempfile
import unittest
from pathlib import Path
from unittest.mock import AsyncMock, patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "scripts"))
import qq_mail as bridge
import qq_mail_write as write_flow


class AttachmentContractTests(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="qq-attachment-contract-")
        self.root = Path(self.temp.name).resolve()
        self.content = (b"synthetic attachment\n" * 6000)[:105571]
        self.metadata = {"message_id": "msg_fixture", "attachment_count": 1, "attachments": [{
            "attachment_id": "att_fixture", "size": len(self.content),
            "filename": "fixture.pdf", "content_type": "application/pdf"}]}
        self.payload = {"content": base64.b64encode(self.content).decode("ascii"),
                        "filename": "fixture.pdf", "content_type": "application/pdf"}

    def tearDown(self):
        self.temp.cleanup()

    def mail(self, metadata=None, payload=None):
        async def call(tool, arguments):
            self.assertEqual(arguments["alias_id"], "alias_fixture")
            self.assertEqual(arguments["message_id"], "msg_fixture")
            if tool == "GetMessage":
                self.assertNotIn("attachment_id", arguments)
                return self.metadata if metadata is None else metadata
            self.assertEqual(tool, "DownloadAttachment")
            self.assertEqual(arguments["attachment_id"], "att_fixture")
            return self.payload if payload is None else payload
        return type("Mail", (), {"alias_id": "alias_fixture", "call": AsyncMock(side_effect=call)})()

    async def download(self, mail=None, name="fixture.pdf"):
        return await bridge.download_attachment(mail or self.mail(), "msg_fixture", "att_fixture", self.root / name)

    async def call_list(self, payload, tool="ListAttachments", error=False):
        mail = object.__new__(bridge.CodexMail)
        raw = {"content": [{"type": "text", "text": json.dumps(payload)}]}
        if error:
            raw["isError"] = True
        mail.raw_call = AsyncMock(return_value=raw)
        return await mail.call(tool, {"message_id": "msg_fixture"})

    async def test_listattachments_real_text_array_is_normalized(self):
        items = self.metadata["attachments"]
        self.assertEqual(await self.call_list(items), {"attachments": items})
        self.assertEqual(await self.call_list([]), {"attachments": []})
        self.assertEqual(await self.call_list(self.metadata), self.metadata)
        wrapped = {"data": {"data": items}, "rsp_headers": {}}
        self.assertEqual(await self.call_list(wrapped), {"attachments": items})

    async def test_listattachments_unknown_invalid_or_error_is_never_empty_success(self):
        valid = self.metadata["attachments"][0]
        cases = (None, "unexpected", {}, {"attachments": None}, ["unexpected"],
                 [{"size": 1}], [{"attachment_id": "att_fixture", "size": True}],
                 [{"attachment_id": "att_fixture", "size": -1}], [valid, valid],
                 [{**valid, "filename": None}], [{**valid, "sha1": "invalid"}])
        for payload in cases:
            with self.assertRaises((RuntimeError, ValueError)):
                await self.call_list(payload)
        with self.assertRaises(bridge.ToolError):
            await self.call_list({"error": "synthetic failure"})
        with self.assertRaises(bridge.ToolError):
            await self.call_list([], error=True)

    async def test_non_attachment_tools_still_require_dict(self):
        for tool in ("GetMessage", "DownloadAttachment", "GetMe"):
            with self.assertRaisesRegex(RuntimeError, "Unexpected QQ Mail response shape"):
                await self.call_list([], tool=tool)

    async def test_content_only_response_uses_bound_metadata_and_local_digest(self):
        result = await self.download()
        self.assertEqual(result["size"], 105571)
        self.assertEqual((self.root / "fixture.pdf").read_bytes(), self.content)
        self.assertEqual(result["sha1"], hashlib.sha1(self.content).hexdigest())
        self.assertEqual(result["verification"], {
            "message_id": "msg_fixture", "attachment_id": "att_fixture",
            "metadata_source": "GetMessage", "size_verified": True,
            "sha1_source": "local_computed", "server_digests_verified": [],
            "level": "metadata_size_and_local_digest"})
        self.assertEqual((self.root / "fixture.pdf").stat().st_mode & 0o777, 0o600)
        self.assertNotIn(self.payload["content"], json.dumps(result))

    async def test_verified_bytes_supply_complete_send_attachment_fields(self):
        result = await self.download()
        arguments = {"to": [{"email": "fixture@example.com"}], "subject": "fixture changed subject",
                     "body": "complete synthetic source body", "attachments": [{
                         "filename": "fixture.pdf", "content_type": "application/pdf",
                         "size": result["size"], "sha1": result["sha1"],
                         "content": base64.b64encode((self.root / "fixture.pdf").read_bytes()).decode()}]}
        write_flow.validate_arguments("SendMessage", arguments)
        arguments["attachments"][0]["sha1"] = "0" * 40
        with self.assertRaisesRegex(ValueError, "SHA-1"):
            write_flow.validate_arguments("SendMessage", arguments)

    async def test_service_digests_are_verified_and_their_sources_recorded(self):
        self.metadata["attachments"][0]["sha1"] = hashlib.sha1(self.content).hexdigest().upper()
        self.payload["sha256"] = hashlib.sha256(self.content).hexdigest()
        self.payload["md5"] = hashlib.md5(self.content, usedforsecurity=False).hexdigest()
        result = await self.download()
        self.assertEqual(result["verification"]["server_digests_verified"],
                         ["GetMessage.sha1", "DownloadAttachment.sha256", "DownloadAttachment.md5"])
        self.assertEqual(result["verification"]["level"], "server_digest_and_metadata_size")

    async def test_missing_or_ambiguous_metadata_id_stops_before_download(self):
        cases = [{}, {"attachments": self.metadata["attachments"]}, {"message_id": "msg_fixture", "attachments": []}, {"message_id": "msg_fixture", "attachments": [{"id": "att_fixture", "size": 1}]},
                 {"message_id": "msg_fixture", "attachments": [{"attachment_id": "att_other", "size": 1}]},
                 {"message_id": "msg_fixture", "attachments": self.metadata["attachments"] * 2}]
        for metadata in cases:
            with self.subTest(metadata=metadata):
                mail = self.mail(metadata=metadata)
                with self.assertRaises(ValueError):
                    await self.download(mail)
                self.assertEqual(mail.call.await_count, 1)
                self.assertFalse((self.root / "fixture.pdf").exists())

    async def test_wrong_message_or_mailbox_metadata_stops_before_download(self):
        for key in ("message_id", "alias_id"):
            for location in ("list", "item"):
                metadata = json.loads(json.dumps(self.metadata))
                (metadata if location == "list" else metadata["attachments"][0])[key] = "other"
                mail = self.mail(metadata=metadata)
                with self.assertRaisesRegex(ValueError, "different message"):
                    await self.download(mail)
                self.assertEqual(mail.call.await_count, 1)

    async def test_missing_invalid_or_oversize_metadata_size_stops_before_download(self):
        for value in (None, True, "105571", -1, 1048577):
            metadata = {"message_id": "msg_fixture", "attachments": [{"attachment_id": "att_fixture", "size": value}]}
            mail = self.mail(metadata=metadata)
            with self.assertRaisesRegex(ValueError, "size"):
                await self.download(mail)
            self.assertEqual(mail.call.await_count, 1)

    async def test_response_identity_or_size_must_match_metadata(self):
        for fields in ({"size": len(self.content) + 1}, {"size": True}, {"size": None},
                       {"message_id": "other"}, {"alias_id": "other"}, {"attachment_id": "other"}):
            with self.assertRaises(ValueError):
                await self.download(self.mail(payload={**self.payload, **fields}))
            self.assertFalse((self.root / "fixture.pdf").exists())

    async def test_metadata_descriptors_must_not_conflict_with_response(self):
        for fields in ({"filename": "different.txt"}, {"content_type": "text/plain"},
                       {"filename": None}, {"content_type": None}):
            with self.assertRaisesRegex(ValueError, "conflicts"):
                await self.download(self.mail(payload={**self.payload, **fields}))
            self.assertFalse((self.root / "fixture.pdf").exists())
        result = await self.download(self.mail(payload={**self.payload, "content_type": "APPLICATION/PDF"}))
        self.assertEqual(result["state"], "downloaded")

    async def test_actual_length_must_match_metadata(self):
        self.metadata["attachments"][0]["size"] -= 1
        with self.assertRaisesRegex(ValueError, "decoded size"):
            await self.download()
        self.assertFalse((self.root / "fixture.pdf").exists())

    async def test_strict_canonical_base64_and_decoded_limit(self):
        for value in ("not-base64!", "YQ==\n", "YR==", "YQ===", "é", "YQ==YQ==",
                      base64.b64encode(b"x" * 1048577).decode()):
            with self.assertRaises(ValueError):
                await self.download(self.mail(payload={**self.payload, "content": value}))
            self.assertFalse((self.root / "fixture.pdf").exists())

    async def test_provided_digest_invalid_unknown_or_mismatched_stops(self):
        for fields in ({"sha1": "0" * 40}, {"sha256": "0" * 64}, {"md5": "0" * 32},
                       {"sha1": None}, {"sha1": "invalid"}, {"checksum": "unknown"}):
            for source in ("metadata", "response"):
                metadata = json.loads(json.dumps(self.metadata))
                payload = dict(self.payload)
                (metadata["attachments"][0] if source == "metadata" else payload).update(fields)
                with self.assertRaises(ValueError):
                    await self.download(self.mail(metadata, payload))
                self.assertFalse((self.root / "fixture.pdf").exists())

    async def test_zero_and_exact_maximum_bytes_are_supported(self):
        for number, content in enumerate((b"", b"x" * 1048576)):
            metadata = {"message_id": "msg_fixture", "attachments": [{"attachment_id": "att_fixture", "size": len(content)}]}
            payload = {"content": base64.b64encode(content).decode()}
            result = await self.download(self.mail(metadata, payload), name=str(number))
            self.assertEqual(result["size"], len(content))
            self.assertEqual((self.root / str(number)).read_bytes(), content)

    async def test_file_sync_failure_never_publishes(self):
        with patch.object(bridge.os, "fsync", side_effect=OSError("synthetic disk failure")):
            with self.assertRaises(OSError):
                await self.download()
        self.assertFalse((self.root / "fixture.pdf").exists())
        self.assertFalse(list(self.root.glob(".qq-attachment-*")))

    async def test_directory_sync_failure_does_not_report_success_or_overwrite(self):
        with patch.object(bridge, "sync_directory", side_effect=OSError("synthetic directory failure")):
            with self.assertRaises(OSError):
                await self.download()
        self.assertEqual((self.root / "fixture.pdf").read_bytes(), self.content)
        with self.assertRaisesRegex(ValueError, "already exists"):
            await self.download()
        self.assertFalse(list(self.root.glob(".qq-attachment-*")))

    async def test_unsafe_parent_permissions_or_symlink_stop_before_calls(self):
        unsafe = self.root / "unsafe"
        unsafe.mkdir(mode=0o700)
        os.chmod(unsafe, 0o777)
        linked = self.root / "linked"
        linked.symlink_to(unsafe, target_is_directory=True)
        mail = self.mail()
        for directory in (unsafe, linked):
            with self.assertRaises(ValueError):
                await bridge.download_attachment(mail, "msg_fixture", "att_fixture", directory / "file")
        mail.call.assert_not_called()


if __name__ == "__main__":
    unittest.main()
